function [allData, scnro, sensor] = StraightRoad4Vehicles()
%StraightRoad4Vehicles - Returns sensor detections
%    allData = StraightRoad4Vehicles returns sensor detections in a structure
%    with time for an internally defined scenario and sensor suite.
%
%    [allData, scenario, sensors] = StraightRoad4Vehicles optionally returns
%    the drivingScenario and detection generator objects.

% Generated by MATLAB(R) 26.2 (R2026b) and Automated Driving Toolbox 26.2 (R2026b).
% Generated on: 17-Oct-2026 12:26:22

% Create the drivingScenario object and ego car
[scnro, egoVehicle] = createDrivingScenario;

% Create all the sensors
sensor = createSensor(scnro);

% Add sensor to scenario
addSensors(scnro, sensor, egoVehicle.ActorID);

allData = struct('Time', {}, 'ActorPoses', {}, 'ObjectDetections', {}, 'LaneDetections', {}, 'PointClouds', {}, 'INSMeasurements', {});
running = true;
while running

    time  = scnro.SimulationTime;

    if ~isa(sensor,'insSensor')
        poses = targetPoses(scnro,sensor.SensorIndex);
    end
    % Generate detections for the sensor
    laneDetections = [];
    ptClouds = [];
    insMeas = [];
    [objectDetections, isValidTime] = sensor(poses, time);
    numObjects = length(objectDetections);
    objectDetections = objectDetections(1:numObjects);

    % Aggregate all detections into a structure for later use
    if isValidTime
        allData(end + 1) = struct( ...
            'Time',       scnro.SimulationTime, ...
            'ActorPoses', actorPoses(scnro), ...
            'ObjectDetections', {objectDetections}, ...
            'LaneDetections', {laneDetections}, ...
            'PointClouds',   {ptClouds}, ... %#ok<AGROW>
            'INSMeasurements',   {insMeas}); %#ok<AGROW>
    end

    % Advance the scenario one time step and exit the loop if the scenario is complete
    running = advance(scnro);
end

% Restart the driving scenario to return the actors to their initial positions.
restart(scnro);

% Release the sensor object so it can be used again.
release(sensor);

%%%%%%%%%%%%%%%%%%%%
% Helper functions %
%%%%%%%%%%%%%%%%%%%%

% Units used in createSensors and createDrivingScenario
% Distance/Position - meters
% Speed             - meters/second
% Angles            - degrees
% RCS Pattern       - dBsm

function sensor = createSensor(scnro)
% createSensors Returns all sensor objects to generate detections

% Assign into each sensor the physical and radar profiles for all actors
profiles = actorProfiles(scnro);
sensor = drivingRadarDataGenerator(SensorIndex = 1, ...
    MountingLocation = [3.7 0 0.2], ...
    RangeLimits = [0 100], ...
    TargetReportFormat = 'Detections', ...
    Profiles = profiles);

function [scnro, egoVehicle] = createDrivingScenario
% createDrivingScenario Returns the drivingScenario defined in the Designer

% Construct a drivingScenario object.
scnro = drivingScenario(StopTime = 14.34);

% Add all road segments
roadCenters = [0 0 0;
    50 0 0;
    100 0 0;
    250 20 0;
    500 40 0];
laneSpecification = lanespec(2);
road(scnro, roadCenters, Lanes = laneSpecification, Name = 'Road');

% Add the actors
x = vehicle(scnro, ...
    ClassID = 1, ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [0.066 0.443 0.745]);
waypoints = [50 -1.8 0;
    100 -1.8 0;
    250 18.2 0;
    500 38.2 0];
speed = 25;
trajectory(x, waypoints, speed);

x = vehicle(scnro, ...
    ClassID = 1, ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [0.866 0.329 0]);
waypoints = [70 -1.8 0;
    100 -1.8 0;
    250 18.2 0;
    500 38.2 0];
speed = 25;
trajectory(x, waypoints, speed);

x = vehicle(scnro, ...
    ClassID = 1, ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [0.929 0.694 0.125]);
waypoints = [0 -1.8 0;
    50 1.8 0;
    100 1.8 0;
    250 21.8 0;
    400 32.2 0;
    500 38.2 0];
speed = 35;
trajectory(x, waypoints, speed);

% Add the ego vehicle
egoVehicle = vehicle(scnro, ...
    ClassID = 1, ...
    Mesh = driving.scenario.carMesh, ...
    PlotColor = [0.521 0.086 0.819]);
waypoints = [25 -1.8 0;
    50 -1.8 0;
    100 -1.8 0;
    250 18.2 0;
    500 38.2 0];
speed = 25;
trajectory(egoVehicle, waypoints, speed);

